def _make_key_and_envelope(stack, algorithm="AES256"):
    c = stack.client
    status, key = c.call("POST", "/v1/keys", {
        "tenant_id": "t", "algorithm": algorithm, "label": "k"})
    assert status == 201, key
    status, enc = c.call("POST", "/v1/keys/%s/encrypt" % key["key_id"], {
        "tenant_id": "t", "plaintext": b64(b"hello"), "aad": b64(b"a")},
        headers={"Idempotency-Key": "enc-1"})
    assert status == 200, enc
    return key["key_id"], enc["envelope"]

